const CME_OFFLINE_KIT_KEY='cme-smart-offline-kit-v1';const CME_KIT_CHECKS=[['passport','Passport / travel document reminder'],['bookings','Booking confirmations saved offline'],['hotel','Hotel Chinese address saved'],['insurance','Travel insurance information saved'],['contacts','Emergency contact saved'],['translation','Offline translation downloaded'],['connectivity','SIM / eSIM or roaming plan checked'],['backup','Printed or second-device backup prepared']];function cmeKitRead(){try{return JSON.parse(localStorage.getItem(CME_OFFLINE_KIT_KEY)||'{}')}catch(e){return {}}}function cmeKitRender(){const data=cmeKitRead();['hotel','hotel-cn','hotel-en','booking','contact','phone','insurance','notes'].forEach(k=>{const el=document.getElementById('cme-kit-'+k);if(el)el.value=data[k]||''});const display=document.getElementById('cme-kit-address-display');if(display)display.textContent=data['hotel-cn']||'Add your hotel address above';const checks=document.getElementById('cme-kit-checklist');if(checks)checks.innerHTML=CME_KIT_CHECKS.map(([k,label])=>`<label><input type="checkbox" data-kit-check="${k}" ${data.checks?.[k]?'checked':''} onchange="cmeKitSave(true)"><span>${label}</span></label>`).join('');}function cmeKitCollect(){const data={version:1,updatedAt:new Date().toISOString(),checks:{}};['hotel','hotel-cn','hotel-en','booking','contact','phone','insurance','notes'].forEach(k=>{const el=document.getElementById('cme-kit-'+k);data[k]=el?.value||''});document.querySelectorAll('[data-kit-check]').forEach(el=>data.checks[el.dataset.kitCheck]=el.checked);return data}function cmeKitSave(silent=false){const data=cmeKitCollect();try{localStorage.setItem(CME_OFFLINE_KIT_KEY,JSON.stringify(data));cmeKitRender();const status=document.getElementById('cme-kit-status');if(status)status.textContent=silent?'Saved locally.':'Travel kit saved on this device.';return true}catch(e){const status=document.getElementById('cme-kit-status');if(status)status.textContent='Unable to save in this browser. Export a JSON backup instead.';return false}}function cmeKitCopy(key){const data=cmeKitCollect();const value=key==='hotel-cn'?data['hotel-cn']:'';if(!value){alert('Add the Chinese hotel address first.');return}copyText(value)}function cmeKitCopyPhrase(value){copyText(value)}function cmeKitExport(){const data=cmeKitCollect();const blob=new Blob([JSON.stringify({app:'China Made Easy',type:'smart-offline-travel-kit',...data},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='china-made-easy-offline-travel-kit.json';a.click();URL.revokeObjectURL(url);const status=document.getElementById('cme-kit-status');if(status)status.textContent='JSON travel kit exported.'}function cmeKitImportFile(input){const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(!parsed||typeof parsed!=='object')throw new Error('Invalid data');localStorage.setItem(CME_OFFLINE_KIT_KEY,JSON.stringify(parsed));cmeKitRender();document.getElementById('cme-kit-status').textContent='Travel kit imported.'}catch(e){document.getElementById('cme-kit-status').textContent='Import failed: file is not a valid travel kit JSON.'}input.value=''};reader.readAsText(file)}function cmeKitPrint(){const kit=cmeKitCollect();const checks=CME_KIT_CHECKS.map(([k,label])=>`<li>${kit.checks[k]?'☑':'☐'} ${label}</li>`).join('');const w=window.open('','_blank');if(!w){alert('Allow pop-ups to print the travel kit.');return}w.document.write(`<html><head><title>Offline Travel Kit</title><meta charset="utf-8"><style>body{font:16px Arial,sans-serif;max-width:760px;margin:32px auto;padding:0 20px;color:#222}h1,h2{color:#234c37}section{border:1px solid #ddd;border-radius:12px;padding:16px;margin:14px 0}li{margin:8px 0;line-height:1.4}.cn{font-size:22px;font-weight:bold}small{color:#555}</style><style id="phase80-auto-fix">.cme-phase80-panel{margin:12px 0;border:1px solid #d5e3d6;background:#f5faf5;border-radius:13px;padding:12px}.cme-phase80-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.cme-phase80-panel p{font-size:12px;color:var(--muted);margin:5px 0}.cme-phase80-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.cme-phase80-preview{border:1px solid #dce6dc;background:#fff;border-radius:10px;padding:10px;margin-top:10px}.cme-phase80-preview ul{padding-left:20px;margin:7px 0}.cme-phase80-preview li{margin:7px 0;font-size:13px}.cme-phase80-change{display:grid;grid-template-columns:1fr;gap:3px}.cme-phase80-before{color:#9a5147;text-decoration:line-through}.cme-phase80-after{color:#326f48;font-weight:700}.cme-phase80-status{font-size:12px;color:#326f48;font-weight:700;margin-top:8px}@media(max-width:600px){.cme-phase80-head{align-items:flex-start;flex-direction:column}}</style>
</head><body><h1>China Made Easy · Offline Travel Kit</h1><section><h2>Accommodation</h2><p><b>${escapeHtml(kit.hotel||'—')}</b></p><p class="cn">${escapeHtml(kit['hotel-cn']||'—')}</p><p>${escapeHtml(kit['hotel-en']||'')}</p><p>Booking reference: ${escapeHtml(kit.booking||'—')}</p></section><section><h2>Emergency & assistance</h2><p>Contact: ${escapeHtml(kit.contact||'—')} · ${escapeHtml(kit.phone||'—')}</p><p>Insurance assistance: ${escapeHtml(kit.insurance||'—')}</p></section><section><h2>Notes</h2><p>${escapeHtml(kit.notes||'—').replace(/\n/g,'<br>')}</p></section><section><h2>Checklist</h2><ul>${checks}</ul></section><section><h2>Useful Chinese phrases</h2><p>请帮帮我。 — Please help me.</p><p>请带我去这个地址。 — Please take me to this address.</p><p>我需要去医院。 — I need to go to a hospital.</p><p>我听不懂，请慢一点。 — I don't understand. Please speak slowly.</p><p>我的护照丢了。 — I lost my passport.</p><p>请帮我报警。 — Please call the police.</p></section><p><small>Generated locally. Confirm emergency numbers and travel details from official sources.</small></p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();}
function cmeKitClear(){if(!confirm('Clear the saved offline travel kit from this browser?'))return;localStorage.removeItem(CME_OFFLINE_KIT_KEY);cmeKitRender();document.getElementById('cme-kit-status').textContent='Saved kit cleared.'}
document.addEventListener('DOMContentLoaded',cmeKitRender);